using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

public sealed class WebSearchTool(IHttpClientFactory httpClientFactory)
{
    [Description("Search the web for information on a given query. Returns a list of results with titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        using var client = httpClientFactory.CreateClient("WebSearch");
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var response = await client.GetAsync(
                $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1&no_html=1");
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadFromJsonAsync<JsonElement>();
            var results = new List<object>();

            // Extract the abstract if available
            var abstractText = json.GetProperty("Abstract").GetString();
            var abstractUrl = json.GetProperty("AbstractURL").GetString();
            var abstractSource = json.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add(new { Title = $"Summary from {abstractSource}", Url = abstractUrl, Snippet = abstractText });
            }

            // Extract related topics
            if (json.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray())
                {
                    if (results.Count >= maxResults) break;
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var url = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add(new { Title = text?[..Math.Min(text.Length, 80)], Url = url, Snippet = text });
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try rephrasing the search query.";
            }

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}. Try again with a different query.";
        }
    }
}

using System.ComponentModel;
using System.Text;

namespace ResearchAgent;

public sealed class NoteTakingTool
{
    private readonly List<(string Topic, string Content, DateTime Timestamp)> _notes = [];

    [Description("Save a research note with a topic label and content. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("A short topic label for the note")] string topic,
        [Description("The content of the note")] string content)
    {
        _notes.Add((topic, content, DateTime.UtcNow));
        return $"Note saved under topic '{topic}'. You now have {_notes.Count} note(s) total.";
    }

    [Description("Retrieve all saved research notes. Use this to review findings before writing a summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet. Use SaveNote to record findings from your research.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===");
        for (var i = 0; i < _notes.Count; i++)
        {
            var (topic, content, timestamp) = _notes[i];
            sb.AppendLine($"\n--- Note {i + 1}: [{topic}] ---");
            sb.AppendLine(content);
        }
        return sb.ToString();
    }

    [Description("Search notes by topic keyword. Returns notes whose topic contains the keyword.")]
    public string SearchNotes(
        [Description("The keyword to search for in note topics")] string keyword)
    {
        var matches = _notes
            .Where(n => n.Topic.Contains(keyword, StringComparison.OrdinalIgnoreCase))
            .ToList();

        if (matches.Count == 0)
            return $"No notes found matching '{keyword}'.";

        var sb = new StringBuilder();
        sb.AppendLine($"Found {matches.Count} note(s) matching '{keyword}':");
        foreach (var (topic, content, _) in matches)
        {
            sb.AppendLine($"\n--- [{topic}] ---");
            sb.AppendLine(content);
        }
        return sb.ToString();
    }
}

