+    private readonly List<(string Topic, string Content, DateTime Timestamp)> _notes = [];
+
+    [Description("Save a research note with a topic label and content. Use this to record important findings during research.")]
+    public string SaveNote(
+        [Description("A short topic label for the note")] string topic,
+        [Description("The content of the note")] string content)
+    {
+        _notes.Add((topic, content, DateTime.UtcNow));
+        return $"Note saved under topic '{topic}'. You now have {_notes.Count} note(s) total.";
+    }
+
+    [Description("Retrieve all saved research notes. Use this to review findings before writing a summary.")]
+    public string GetAllNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet. Use SaveNote to record findings from your research.";
+
+        var sb = new StringBuilder();
+        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===");
+        for (var i = 0; i < _notes.Count; i++)
+        {
+            var (topic, content, timestamp) = _notes[i];
+            sb.AppendLine($"\n--- Note {i + 1}: [{topic}] ---");
+            sb.AppendLine(content);
+        }
+        return sb.ToString();
+    }
+
+    [Description("Search notes by topic keyword. Returns notes whose topic contains the keyword.")]
+    public string SearchNotes(
+        [Description("The keyword to search for in note topics")] string keyword)
+    {
+        var matches = _notes
+            .Where(n => n.Topic.Contains(keyword, StringComparison.OrdinalIgnoreCase))
+            .ToList();
+
+        if (matches.Count == 0)
+            return $"No notes found matching '{keyword}'.";
+
+        var sb = new StringBuilder();
+        sb.AppendLine($"Found {matches.Count} note(s) matching '{keyword}':");
+        foreach (var (topic, content, _) in matches)
+        {
+            sb.AppendLine($"\n--- [{topic}] ---");
+            sb.AppendLine(content);
+        }
+        return sb.ToString();
+    }
+}
+

