using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI.ChatCompletion;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

// Require an API key — load from environment or user-secrets
var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in user-secrets.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

// Register HttpClient for web search
builder.Services.AddHttpClient("WebSearch");

// Register AI tools
builder.Services.AddSingleton<NoteTakingTool>();
builder.Services.AddSingleton<WebSearchTool>();

// Register the chat client via MEAI abstraction
builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .UseOpenAIChatClient(modelId, apiKey));

var host = builder.Build();

// Resolve services
var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteTool = host.Services.GetRequiredService<NoteTakingTool>();
var webSearchTool = host.Services.GetRequiredService<WebSearchTool>();

// Build the agent with tools
var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    "You are a thorough research agent. When given a topic, you:\n" +
    "1. Search the web for relevant information using multiple queries\n" +
    "2. Save important findings as notes with descriptive topic labels\n" +
    "3. Review all your notes\n" +
    "4. Produce a well-structured summary with key findings\n\n" +
    "Always search at least 2-3 different angles of the topic. " +
    "Save notes for each significant finding before summarizing.",
    [AIFunctionFactory.Create(webSearchTool.SearchWebAsync),
     AIFunctionFactory.Create(noteTool.SaveNote),
     AIFunctionFactory.Create(noteTool.GetAllNotes),
     AIFunctionFactory.Create(noteTool.SearchNotes)]);

// Get the research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n{"",0,60}");
Console.WriteLine("Working...\n");

// Run the agent with iteration limits
var options = new AgentInvokeOptions { MaximumIterations = 15 };
var chatOptions = new ChatOptions { Temperature = 0f, MaxOutputTokens = 4096 };
var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic and provide a comprehensive summary: {topic}")
};

string? finalResponse = null;
await foreach (var message in agent.InvokeStreamingAsync(history, options, chatOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
        finalResponse = (finalResponse ?? "") + message.Text;
    }
}

Console.WriteLine("\n\n--- Research Complete ---");

